-- Hindi Word EFFICIENCY TEST 7: a new paper (24 Nov 2026). The old one asked the same kinds of questions as Tests 5, 6
-- and 8 (font size/colour, Change Case, superscript, Justify + line spacing, numbering, sort, Replace All, Page Break,
-- Insert Table, ©, header + page number, page border, Orientation + Margins). Every new question asks for a Word 2013
-- tool that no other Word Efficiency paper (Hindi or English) uses:
--   HOME Font: Grow Font (A↑) twice, Small caps, Hidden.   HOME Paragraph: Spacing Before 24 pt, Checkmark bullets.
--   TABLE TOOLS: Table Style "Grid Table 4 - Accent 1", Alignment Center, Delete Columns, Repeat Header Rows.
--   DESIGN: Page Border > Options > Measure from Text.
--   PAGE LAYOUT: Two Columns, Line Numbers, Hyphenation, Gutter 1", Section Break (Next Page).
-- Same practice document. The test gets a NEW version (students' earlier attempts stay on their own version with their
-- marks), with hand-written checks, Hindi solutions and the Model Answer solved in the real editor; results are
-- published automatically. The tools the questions need are switched on in the new version's editor settings.
-- Generated by scripts/build-hindi-word-test7-v2-migration.mjs. Safe to run twice (skipped once Test 7 has this paper).
begin;

create temporary table new_paper (questions jsonb, model jsonb) on commit drop;
insert into new_paper values ($q$[{"number":1,"instruction":"प्रथम पैराग्राफ (हिंदी) का फॉन्ट साइज Grow Font (A↑) बटन से दो बार बढ़ाइए (14 से 18)।","marks":1.66,"criteria":[{"rule":"words","kind":"body","place":0,"props":{"fontSize":[18],"fontFamily":{"regex":"^kruti dev"}}}],"solution":"1. पहला (हिंदी) पैराग्राफ सेलेक्ट करें।\n2. HOME → **Grow Font (A↑)** दो बार दबाएँ (Ctrl+Shift+>)। साइज 14 → 16 → **18**।\n\nजाँच: पहला पैराग्राफ साइज 18, फॉन्ट Kruti Dev 010 ही रहे।"},{"number":2,"instruction":"चतुर्थ पैराग्राफ (The Home tab contains…) को Font डायलॉग से Small caps इफेक्ट दीजिए।","marks":1.66,"criteria":[{"rule":"words","kind":"body","place":3,"props":{"smallCaps":[true]}}],"solution":"1. चौथा पैराग्राफ (\"The Home tab contains…\") सेलेक्ट करें।\n2. HOME → Font ग्रुप **↘** (Ctrl+D) → Effects में **Small caps** ✔ → **OK**।\n\nजाँच: छोटे अक्षर छोटे कैपिटल अक्षरों में दिखें।"},{"number":3,"instruction":"\"Einstein's famous formula is E = mc2\" लाइन को Font डायलॉग से Hidden (छिपा हुआ) कीजिए।","marks":1.66,"criteria":[{"rule":"words","kind":"body","place":8,"props":{"hidden":[true]}}],"solution":"1. \"Einstein's famous formula is E = mc2\" लाइन सेलेक्ट करें।\n2. HOME → Font ग्रुप **↘** (Ctrl+D) → Effects में **Hidden** ✔ → **OK**।\n\nजाँच: लाइन पेज पर दिखनी बंद हो जाए (¶ Show/Hide चालू करने पर डॉटेड अंडरलाइन के साथ दिखेगी)।"},{"number":4,"instruction":"द्वितीय पैराग्राफ (Microsoft Word is…) के ऊपर Spacing Before 24 pt दीजिए।","marks":1.66,"criteria":[{"rule":"value","kind":"body","place":1,"target":"blocks.0.attrs.marginTop","spec":{"regex":"^24(\\.0+)?(pt)?$"}}],"solution":"1. दूसरे पैराग्राफ में क्लिक करें।\n2. HOME → Paragraph ग्रुप **↘** → Spacing **Before: 24 pt** → **OK** (या PAGE LAYOUT → Spacing Before **24 pt**)।\n\nजाँच: दूसरे पैराग्राफ के ऊपर ज़्यादा जगह।"},{"number":5,"instruction":"दी गई सूची (Home Tab, Insert Tab…) की बुलेट्स को Bullet Library के Checkmark (✓) बुलेट में बदलिए।","marks":1.66,"criteria":[{"rule":"value","kind":"body","place":4,"target":"blocks.0.attrs.listStyle","spec":["bullet-check"]},{"rule":"value","kind":"body","place":5,"target":"blocks.0.attrs.listStyle","spec":["bullet-check"]},{"rule":"value","kind":"body","place":6,"target":"blocks.0.attrs.listStyle","spec":["bullet-check"]},{"rule":"value","kind":"body","place":7,"target":"blocks.0.attrs.listStyle","spec":["bullet-check"]}],"solution":"1. सूची के चारों आइटम सेलेक्ट करें।\n2. HOME → **Bullets ▾** → Bullet Library में **✓ (Checkmark)**।\n\nजाँच: चारों आइटम के आगे ✓।"},{"number":6,"instruction":"टेबल पर Table Style \"Grid Table 4 - Accent 1\" लगाइए।","marks":1.66,"criteria":[{"rule":"table","place":0,"attrs":{"tableStyle":["grid-4-accent-1"]}}],"solution":"1. टेबल में क्लिक करें।\n2. TABLE TOOLS → **DESIGN** → Table Styles ▾ → Grid Tables में **Grid Table 4 - Accent 1** (नीली हेडिंग वाली)।\n\nजाँच: टेबल की पहली रो नीली, बाकी रो धारीदार।"},{"number":7,"instruction":"टेबल को Table Properties से पेज के बीच में (Alignment: Center) कीजिए।","marks":1.66,"criteria":[{"rule":"table","place":0,"attrs":{"tableAlign":["center"]}}],"solution":"1. टेबल में क्लिक करें।\n2. TABLE TOOLS → **LAYOUT** → **Properties** → **Table** टैब → Alignment **Center** → **OK**।\n\nजाँच: पूरी टेबल पेज के बीच में।"},{"number":8,"instruction":"टेबल का \"City\" कॉलम डिलीट कीजिए।","marks":1.66,"criteria":[{"rule":"table","place":0,"columns":3,"headerAt":{"0":"S.No.","1":"Name","2":"Marks"}}],"solution":"1. टेबल के \"City\" कॉलम के किसी सेल में क्लिक करें।\n2. TABLE TOOLS → **LAYOUT** → **Delete ▾** → **Delete Columns**।\n\nजाँच: टेबल में S.No., Name, Marks — तीन कॉलम।"},{"number":9,"instruction":"टेबल की पहली रो को Repeat Header Rows कीजिए, ताकि वह हर पेज पर दोहराई जाए।","marks":1.66,"criteria":[{"rule":"table","place":0,"attrs":{"repeatHeader":[true]}}],"solution":"1. टेबल की पहली रो (S.No., Name…) में क्लिक करें।\n2. TABLE TOOLS → **LAYOUT** → Data ग्रुप में **Repeat Header Rows**।\n\nजाँच: Repeat Header Rows बटन चालू दिखे।"},{"number":10,"instruction":"पेज पर Box पेज बॉर्डर (Dotted लाइन, कलर Green) दीजिए और Options में Measure from: Text कीजिए।","marks":1.66,"criteria":[{"rule":"value","target":"pageLayout.border","spec":{"regex":"^(?!.*sides:)\\S+ dotted (#00B050|rgb\\(0, ?176, ?80\\)).* measure:text"}}],"solution":"1. DESIGN → **Page Borders**।\n2. Setting **Box**, Style **डॉटेड लाइन (·····)**, Color **Green**।\n3. **Options…** → Measure from **Text** → **OK** → **OK**।\n\nजाँच: हरी डॉटेड बॉर्डर टेक्स्ट के पास (पेज के किनारे से नहीं)।"},{"number":11,"instruction":"पूरे डॉक्यूमेंट को Two कॉलम (Columns) में कीजिए।","marks":1.66,"criteria":[{"rule":"value","target":"pageLayout.columnCount","spec":["2",2]}],"solution":"1. PAGE LAYOUT → **Columns ▾** → **Two**।\n\nजाँच: टेक्स्ट दो कॉलम में।"},{"number":12,"instruction":"डॉक्यूमेंट में Line Numbers (Continuous) लगाइए।","marks":1.66,"criteria":[{"rule":"value","kind":"body","place":0,"target":"blocks.0.attrs.lineNumbers","spec":[true]},{"rule":"value","kind":"body","place":1,"target":"blocks.0.attrs.lineNumbers","spec":[true]},{"rule":"value","kind":"body","place":2,"target":"blocks.0.attrs.lineNumbers","spec":[true]},{"rule":"value","kind":"body","place":3,"target":"blocks.0.attrs.lineNumbers","spec":[true]}],"solution":"1. PAGE LAYOUT → **Line Numbers ▾** → **Continuous**।\n\nजाँच: हर लाइन के बाईं ओर 1, 2, 3… नंबर।"},{"number":13,"instruction":"डॉक्यूमेंट में Hyphenation Automatic कीजिए।","marks":1.66,"criteria":[{"rule":"value","kind":"body","place":0,"target":"blocks.0.attrs.hyphens","spec":["auto"]},{"rule":"value","kind":"body","place":1,"target":"blocks.0.attrs.hyphens","spec":["auto"]},{"rule":"value","kind":"body","place":2,"target":"blocks.0.attrs.hyphens","spec":["auto"]},{"rule":"value","kind":"body","place":3,"target":"blocks.0.attrs.hyphens","spec":["auto"]}],"solution":"1. PAGE LAYOUT → **Hyphenation ▾** → **Automatic**।\n\nजाँच: लाइन के अंत के लंबे शब्द ज़रूरत पर हाइफ़न (-) से टूटें।"},{"number":14,"instruction":"Page Setup से बाईं ओर 1\" का Gutter दीजिए।","marks":1.66,"criteria":[{"rule":"value","target":"pageLayout.gutter","spec":{"regex":"^(25\\.4|2\\.54|1)(0*)?(mm|cm|in)?$"}}],"solution":"1. PAGE LAYOUT → **Margins ▾** → **Custom Margins…**।\n2. Gutter **1\"**, Gutter position **Left** → **OK**।\n\nजाँच: बायाँ मार्जिन 1\" ज़्यादा चौड़ा।"},{"number":15,"instruction":"टेबल से ठीक पहले Section Break (Next Page) लगाइए।","marks":1.76,"criteria":[{"rule":"value","kind":"body","place":10,"target":"blocks.0.type","spec":["section-break"]}],"solution":"1. \"Samradhi Classes, Jaipur\" लाइन के अंत में क्लिक करें (टेबल से ठीक पहले)।\n2. PAGE LAYOUT → **Breaks ▾** → Section Breaks में **Next Page**।\n\nजाँच: टेबल नए सेक्शन के नए पेज पर।"}]$q$::jsonb, $q${"schemaVersion":"2","blocks":[{"id":"block-0","type":"paragraph","alignment":"justify","runs":[{"text":"dEI;wVj vkt gekjs thou dk ,d egRoiw.kZ vax cu x;k gSA cSad] jsyos] vLirky vkSj ljdkjh dk;kZy;ksa esa vf/kdrj dke dEI;wVj dh lgk;rk ls rst+h ls fd, tkrs gSaA jktLFkku deZpkjh p;u cksMZ dh ijh{kkvksa esa Hkh dEI;wVj dk Kku vko';d gSA tks vH;FkhZ fu;fer vH;kl djrs gSa] os Vkbfiax vkSj n{krk ijh{kk esa vPNs vad izkIr djrs gSaA","bold":false,"italic":false,"underline":false,"underlineStyle":null,"underlineColor":null,"underlineThickness":null,"underlineWordsOnly":false,"strike":false,"doubleStrike":false,"superscript":false,"subscript":false,"smallCaps":false,"allCaps":false,"hidden":false,"outline":false,"emboss":false,"fontFamily":"Kruti Dev 010","fontSize":18,"color":"020618","highlight":null,"charScale":null,"charSpacing":null,"charPosition":null,"kerningEnabled":false,"kerningMin":null,"href":null,"bookmark":null,"field":null}],"attrs":{"marginLeft":"0pt","marginRight":"0pt","lineHeight":"1.15","marginTop":"0pt","marginBottom":"8pt","hyphens":"auto","lineNumbers":true,"dropCap":false}},{"id":"block-1","type":"paragraph","alignment":"left","runs":[{"text":"Microsoft Word is a word processing program that helps you create a professional document in a short time. You can type text, format it, inse