"doubleStrike":false,"superscript":false,"subscript":false,"smallCaps":false,"allCaps":false,"hidden":false,"outline":false,"emboss":false,"fontFamily":"Segoe UI","fontSize":12,"color":"020618","highlight":null,"charScale":null,"charSpacing":null,"charPosition":null,"kerningEnabled":false,"kerningMin":null,"href":null,"bookmark":null,"field":null},{"text":"Pooja","bold":false,"italic":false,"underline":false,"underlineStyle":null,"underlineColor":null,"underlineThickness":null,"underlineWordsOnly":false,"strike":false,"doubleStrike":false,"superscript":false,"subscript":false,"smallCaps":false,"allCaps":false,"hidden":false,"outline":false,"emboss":false,"fontFamily":"Segoe UI","fontSize":12,"color":"020618","highlight":null,"charScale":null,"charSpacing":null,"charPosition":null,"kerningEnabled":false,"kerningMin":null,"href":null,"bookmark":null,"field":null},{"text":"91","bold":false,"italic":false,"underline":false,"underlineStyle":null,"underlineColor":null,"underlineThickness":null,"underlineWordsOnly":false,"strike":false,"doubleStrike":false,"superscript":false,"subscript":false,"smallCaps":false,"allCaps":false,"hidden":false,"outline":false,"emboss":false,"fontFamily":"Segoe UI","fontSize":12,"color":"020618","highlight":null,"charScale":null,"charSpacing":null,"charPosition":null,"kerningEnabled":false,"kerningMin":null,"href":null,"bookmark":null,"field":null},{"text":"5","bold":true,"italic":false,"underline":false,"underlineStyle":null,"underlineColor":null,"underlineThickness":null,"underlineWordsOnly":false,"strike":false,"doubleStrike":false,"superscript":false,"subscript":false,"smallCaps":false,"allCaps":false,"hidden":false,"outline":false,"emboss":false,"fontFamily":"Segoe UI","fontSize":12,"color":"020618","highlight":null,"charScale":null,"charSpacing":null,"charPosition":null,"kerningEnabled":false,"kerningMin":null,"href":null,"bookmark":null,"field":null},{"text":"Anil","bold":false,"italic":false,"underline":false,"underlineStyle":null,"underlineColor":null,"underlineThickness":null,"underlineWordsOnly":false,"strike":false,"doubleStrike":false,"superscript":false,"subscript":false,"smallCaps":false,"allCaps":false,"hidden":false,"outline":false,"emboss":false,"fontFamily":"Segoe UI","fontSize":12,"color":"020618","highlight":null,"charScale":null,"charSpacing":null,"charPosition":null,"kerningEnabled":false,"kerningMin":null,"href":null,"bookmark":null,"field":null},{"text":"74","bold":false,"italic":false,"underline":false,"underlineStyle":null,"underlineColor":null,"underlineThickness":null,"underlineWordsOnly":false,"strike":false,"doubleStrike":false,"superscript":false,"subscript":false,"smallCaps":false,"allCaps":false,"hidden":false,"outline":false,"emboss":false,"fontFamily":"Segoe UI","fontSize":12,"color":"020618","highlight":null,"charScale":null,"charSpacing":null,"charPosition":null,"kerningEnabled":false,"kerningMin":null,"href":null,"bookmark":null,"field":null}],"attrs":{"rows":[["S.No.","Name","Marks"],["1","Rakesh","68"],["2","Sunita","82"],["3","Mahesh","55"],["4","Pooja","91"],["5","Anil","74"]],"cellFormats":[[{"fontSize":12,"fontFamily":"Segoe UI","bold":true,"color":"FFFFFF"},{"fontSize":12,"fontFamily":"Segoe UI","bold":true,"color":"FFFFFF"},{"fontSize":12,"fontFamily":"Segoe UI","bold":true,"color":"FFFFFF"}],[{"fontSize":12,"fontFamily":"Segoe UI","bold":true,"color":"020618"},{"fontSize":12,"fontFamily":"Segoe UI","color":"020618"},{"fontSize":12,"fontFamily":"Segoe UI","color":"020618"}],[{"fontSize":12,"fontFamily":"Segoe UI","bold":true,"color":"020618"},{"fontSize":12,"fontFamily":"Segoe UI","color":"020618"},{"fontSize":12,"fontFamily":"Segoe UI","color":"020618"}],[{"fontSize":12,"fontFamily":"Segoe UI","bold":true,"color":"020618"},{"fontSize":12,"fontFamily":"Segoe UI","color":"020618"},{"fontSize":12,"fontFamily":"Segoe UI","color":"020618"}],[{"fontSize":12,"fontFamily":"Segoe UI","bold":true,"color":"020618"},{"fontSize":12,"fontFamily":"Segoe UI","color":"020618"},{"fontSize":12,"fontFamily":"Segoe UI","color":"020618"}],[{"fontSize":12,"fontFamily":"Segoe UI","bold":true,"color":"020618"},{"fontSize":12,"fontFamily":"Segoe UI","color":"020618"},{"fontSize":12,"fontFamily":"Segoe UI","color":"020618"}]],"tableStyle":"grid-4-accent-1","headerRow":true,"totalRow":false,"bandedRows":true,"firstColumn":true,"lastColumn":false,"bandedColumns":false,"repeatHeader":true,"tableAlign":"center"}},{"id":"block-12","type":"paragraph","alignment":"left","runs":[{"text":"","bold":false,"italic":false,"underline":false,"underlineStyle":null,"underlineColor":null,"underlineThickness":null,"underlineWordsOnly":false,"strike":false,"superscript":false,"subscript":false,"smallCaps":false,"allCaps":false,"hidden":false,"outline":false,"emboss":false,"fontFamily":null,"fontSize":null,"color":null,"highlight":null,"charScale":null,"charSpacing":null,"charPosition":null,"kerningEnabled":false,"kerningMin":null,"doubleStrike":false,"href":null,"bookmark":null,"field":null}],"attrs":{"lineNumbers":false,"dropCap":false}}],"pageLayout":{"padding":"20mm 20mm 20mm 20mm","gutter":"25.4mm","gutterPosition":"left","maxWidth":"794px","aspectRatio":"21 / 29.7","columnCount":"2","backgroundColor":null,"border":"1px dotted #00B050 measure:text","watermark":null},"operations":["increaseFontSize","fontDialog","paragraphDialog","bullets","insertTable","pageBorders","columns","lineNumbers","hyphenation","margins","sectionBreak"],"savedAt":"2026-11-24T16:03:57.184Z"}$q$::jsonb);

do $$
declare p record; old record; new_id uuid; q jsonb; question_id uuid; caps jsonb; tool text[];
begin
  select * into p from new_paper;
  select v.* into old from public.word_efficiency_tests t join public.word_efficiency_versions v on v.id = t.current_version_id
   where t.language = 'Hindi' and t.title = 'EFFICIENCY TEST 7';
  if old.id is null then raise exception 'Hindi Word EFFICIENCY TEST 7 not found'; end if;
  if exists (select 1 from public.word_efficiency_questions where version_id = old.id and question_number = 1 and instruction = p.questions->0->>'instruction') then
    raise notice 'Hindi Word EFFICIENCY TEST 7 already has the new paper'; return;
  end if;
  caps := coalesce(old.editor_capabilities, '{}'::jsonb);
  foreach tool slice 1 in array array[array['Home','font','increaseFontSize'], array['Home','font','fontDialog'], array['Home','paragraph','bullets'], array['Home','paragraph','paragraphDialog'], array['Insert','tables','insertTable'], array['Design','pageBackground','pageBorders'], array['Page Layout','pageSetup','columns'], array['Page Layout','pageSetup','lineNumbers'], array['Page Layout','pageSetup','margins'], array['Page Layout','pageSetup','sectionBreak']] loop
    caps := jsonb_set(caps, array['tabs'], coalesce(caps->'tabs', '{}'::jsonb));
    caps := jsonb_set(caps, array['tabs', tool[1]], coalesce(caps #> array['tabs', tool[1]], '{}'::jsonb) || '{"enabled": true}');
    caps := jsonb_set(caps, array['tabs', tool[1], 'groups'], coalesce(caps #> array['tabs', tool[1], 'groups'], '{}'::jsonb));
    caps := jsonb_set(caps, array['tabs', tool[1], 'groups', tool[2]], coalesce(caps #> array['tabs', tool[1], 'groups', tool[2]], '{}'::jsonb) || '{"enabled": true}');
    caps := jsonb_set(caps, array['tabs', tool[1], 'groups', tool[2], 'options'], coalesce(caps #> array['tabs', tool[1], 'groups', tool[2], 'options'], '{}'::jsonb));
    caps := jsonb_set(caps, array['tabs', tool[1], 'groups', tool[2], 'options', tool[3]], 'true');
  end loop;
  insert into public.word_efficiency_versions (test_id, version_number, title, language, description, instructions_markdown, delivery_onscreen, delivery_pdf, delivery_realfile,
      student_question_toggle, question_count, maximum_marks, duration_options, passing_marks, created_by, working_matter_snapshot, editor_capabilities, model_answer_snapshot)
  values (old.test_id, (select max(version_number) + 1 from public.word_efficiency_versions where test_id = old.test_id), old.title, old.language, old.description, old.instructions_markdown,
      true, false, false, old.student_question_toggle, jsonb_array_length(p.questions), 25, old.duration_options, old.passing_marks, old.created_by, old.working_matter_snapshot, caps, p.model)
  returning id into new_id;
  for q in select value from jsonb_array_elements(p.questions) loop
    insert into public.word_efficiency_questions (version_id, question_number, instruction, marks, section, display_order, is_visible, solution)
    values (new_id, (q->>'number')::integer, q->>'instruction', (q->>'marks')::numeric, null, (q->>'number')::integer, true, q->>'solution')
    returning id into question_id;
    insert into public.word_efficiency_grading_rules (version_id, question_id, exact_target, expected_operation, expected_value, allocated_marks, partial_marks, additional_criteria, part_label)
    values (new_id, question_id, 'rule', 'model-answer-match-v2', 'null'::jsonb, (q->>'marks')::numeric, null, q->'criteria', null);
  end loop;
  update public.word_efficiency_tests set current_version_id = new_id, current_version_number = (select version_number from public.word_efficiency_versions where id = new_id),
      auto_publish_results = true, updated_at = now()
   where id = old.test_id;
end $$;

-- Check: the Model Answer must earn every question's marks (25), the untouched paper none (0), and every tool the
-- questions need must be switched on (tools_off empty).
select t.title, t.current_version_number, v.question_count, sum(q.marks) total,
       sum((public.word_efficiency_score_question(v.model_answer_snapshot, v.id, q.id, q.marks, v.model_answer_snapshot)).awarded) model_answer_gets,
       sum((public.word_efficiency_score_question(public.word_efficiency_initial_editor_document(v.working_matter_snapshot), v.id, q.id, q.marks, v.model_answer_snapshot)).awarded) untouched_paper_gets,
       (select coalesce(string_agg(tool, ', '), '') from unnest(array['Home/font/increaseFontSize', 'Home/font/fontDialog', 'Home/paragraph/bullets', 'Home/paragraph/paragraphDialog', 'Insert/tables/insertTable', 'Design/pageBackground/pageBorders', 'Page Layout/pageSetup/columns', 'Page Layout/pageSetup/lineNumbers', 'Page Layout/pageSetup/margins', 'Page Layout/pageSetup/sectionBreak']) tool
         where coalesce(v.editor_capabilities #>> array['tabs', split_part(tool, '/', 1), 'groups', split_part(tool, '/', 2), 'options', split_part(tool, '/', 3)], 'false') <> 'true') tools_off
  from public.word_efficiency_tests t join public.word_efficiency_versions v on v.id = t.current_version_id join public.word_efficiency_questions q on q.version_id = v.id
 where t.language = 'Hindi' and t.title = 'EFFICIENCY TEST 7'
 group by t.title, t.current_version_number, v.question_count, v.editor_capabilities;

commit;
